"use client";

// Lightweight i18n — no external library. A language context + a key-major
// translation table + t(key) with English fallback, persisted to localStorage
// and seeded from the browser locale. Key-major (T[key][lang]) keeps every
// string's translations grouped so they stay aligned and are easy to review.
//
// Coverage: the full public landing page. Genuinely technical/demo content
// (the simulated physics PDF, formulas, prices, URLs) stays in English on
// purpose. Machine-seeded — have a native speaker review before a big
// regional campaign. Missing keys/languages fall back to English.

import React, { createContext, useContext, useEffect, useState } from "react";

