interface I18nValue {
  lang: Lang;
  setLang: (l: Lang) => void;
  t: (key: string) => string;
}

const I18nContext = createContext<I18nValue | undefined>(undefined);

const STORAGE_KEY = "bluebottlecap_lang";
const isLang = (v: string | null): v is Lang => !!v && LANGUAGES.some((l) => l.code === v);

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [lang, setLangState] = useState<Lang>("en");

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    const initial = isLang(saved) ? saved : (isLang(navigator.language?.slice(0, 2) ?? null) ? (navigator.language.slice(0, 2) as Lang) : null);
    if (initial) {
      setLangState(initial);
      document.documentElement.lang = initial;
    }
  }, []);

  const setLang = (l: Lang) => {
    setLangState(l);
    try { localStorage.setItem(STORAGE_KEY, l); } catch {}
    if (typeof document !== "undefined") document.documentElement.lang = l;
  };

  const t = (key: string) => T[key]?.[lang] ?? T[key]?.en ?? key;

  return <I18nContext.Provider value={{ lang, setLang, t }}>{children}</I18nContext.Provider>;
}

export function useI18n(): I18nValue {
  const ctx = useContext(I18nContext);
  if (!ctx) return { lang: "en", setLang: () => {}, t: (k) => T[k]?.en ?? k };
  return ctx;
}
